import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // --- Card dimensions (based on atlas 512x320, ~1.6:1) ---
  const W = 2.0;
  const H = 1.25;
  const BORDER = 0.04; // border strip width
  const LIFT = 0.15;   // hover lift distance

  // --- Colors from spec ---
  const colors = config.intent?.visualSpec?.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  // --- Main group ---
  const group = new THREE.Group();

  // --- Image plane ---
  const geo = new THREE.PlaneGeometry(W, H);
  const mat = new MeshBasicNodeMaterial({
    side: THREE.DoubleSide,
    transparent: true,
    color: surface,       // fallback until texture loads
  });
  const plane = new THREE.Mesh(geo, mat);
  group.add(plane);

  // --- Accent edge (thin border strips) ---
  const borderGroup = new THREE.Group();
  const stripMat = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0,
    side: THREE.DoubleSide,
    depthWrite: false,
  });

  // Top strip
  const topStrip = new THREE.Mesh(
    new THREE.PlaneGeometry(W + BORDER * 2, BORDER),
    stripMat.clone()
  );
  topStrip.position.set(0, H / 2 + BORDER / 2, 0.001);

  // Bottom strip
  const bottomStrip = new THREE.Mesh(
    new THREE.PlaneGeometry(W + BORDER * 2, BORDER),
    stripMat.clone()
  );
  bottomStrip.position.set(0, -H / 2 - BORDER / 2, 0.001);

  // Left strip
  const leftStrip = new THREE.Mesh(
    new THREE.PlaneGeometry(BORDER, H),
    stripMat.clone()
  );
  leftStrip.position.set(-W / 2 - BORDER / 2, 0, 0.001);

  // Right strip
  const rightStrip = new THREE.Mesh(
    new THREE.PlaneGeometry(BORDER, H),
    stripMat.clone()
  );
  rightStrip.position.set(W / 2 + BORDER / 2, 0, 0.001);

  borderGroup.add(topStrip, bottomStrip, leftStrip, rightStrip);
  group.add(borderGroup);

  // --- Load texture (async, non-blocking) ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      mat.map = tex;
      mat.needsUpdate = true;
    });
  }

  // --- Store original position for hover reset ---
  const origY = group.position.y;

  // --- Interaction handlers ---
  group.userData.handlers = {
    hover: {
      start: () => {
        // Kill any reverse tweens
        if (group.userData._hoverReverse) {
          group.userData._hoverReverse.kill();
        }

        // Lift
        gsap.to(group.position, {
          y: origY + LIFT,
          duration: 0.3,
          ease: 'power2.out',
          overwrite: 'auto',
        });

        // Fade in border strips
        borderGroup.children.forEach((strip) => {
          gsap.to(strip.material, {
            opacity: 1,
            duration: 0.3,
            ease: 'power2.out',
            overwrite: 'auto',
          });
        });

        group.userData._hoverForward = gsap.to({}, { duration: 0.3, onComplete: () => {} });
      },
      end: () => {
        if (group.userData._hoverForward) {
          group.userData._hoverForward.kill();
        }

        // Return lift
        gsap.to(group.position, {
          y: origY,
          duration: 0.3,
          ease: 'power2.out',
          overwrite: 'auto',
        });

        // Fade out border strips
        borderGroup.children.forEach((strip) => {
          gsap.to(strip.material, {
            opacity: 0,
            duration: 0.3,
            ease: 'power2.out',
            overwrite: 'auto',
          });
        });

        group.userData._hoverReverse = gsap.to({}, { duration: 0.3, onComplete: () => {} });
      },
    },
    click: () => {
      // Press down
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1,
            y: 1,
            duration: 0.3,
            ease: 'power4.out',
            overwrite: 'auto',
          });
        },
      });

      // Emit navigation event
      ctx.emit('hub-journal.select', { nodeId: config.id });
    },
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill all GSAP tweens on group and its children
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    borderGroup.children.forEach((strip) => {
      gsap.killTweensOf(strip.material);
      // Dispose material
      strip.material.dispose();
    });
    [topStrip, bottomStrip, leftStrip, rightStrip].forEach((strip) => {
      strip.geometry.dispose();
    });

    // Dispose main material and geometry
    mat.dispose();
    geo.dispose();

    // Dispose texture if loaded
    if (mat.map) mat.map.dispose();
  };

  return group;
}
